(* [comment removed for export] *)
Lemma le64_lbu_raw : forall b0 b1 b2 b3 b4 b5 b6 b7,
  0 <= b0 < 256 -> 0 <= b1 < 256 -> 0 <= b2 < 256 -> 0 <= b3 < 256 ->
  0 <= b4 < 256 -> 0 <= b5 < 256 -> 0 <= b6 < 256 -> 0 <= b7 < 256 ->
  Z.lor
    (Z.lor (Z.lor (bv_unsigned (Z_to_bv 8 b7) ≪ 24 mod 18446744073709551616)
                  (bv_unsigned (Z_to_bv 8 b6) ≪ 16 mod 18446744073709551616))
           (Z.lor (bv_unsigned (Z_to_bv 8 b5) ≪ 8 mod 18446744073709551616) (bv_unsigned (Z_to_bv 8 b4)))
     ≪ 32 mod 18446744073709551616)
    (Z.lor (Z.lor (bv_unsigned (Z_to_bv 8 b3) ≪ 24 mod 18446744073709551616)
                  (bv_unsigned (Z_to_bv 8 b2) ≪ 16 mod 18446744073709551616))
           (Z.lor (bv_unsigned (Z_to_bv 8 b1) ≪ 8 mod 18446744073709551616) (bv_unsigned (Z_to_bv 8 b0))))
  = b0 + 2^8 * b1 + 2^16 * b2 + 2^24 * b3 + 2^32 * b4 + 2^40 * b5 + 2^48 * b6 + 2^56 * b7.
