(* [comment removed for export] *)
Definition lesmall (bs : list Z) : Z :=
  Znth 0 bs + (if 1 <? zlen bs then Znth 1 bs * 2^8 else 0) + (if 2 <? zlen bs then Znth 2 bs * 2^16 else 0)
  + (if 3 <? zlen bs then Znth 3 bs * 2^24 else 0) + (if 4 <? zlen bs then Znth 4 bs * 2^32 else 0)
  + (if 5 <? zlen bs then Znth 5 bs * 2^40 else 0) + (if 6 <? zlen bs then Znth 6 bs * 2^48 else 0).

